import { useState } from 'react';

type ExpansionState = {
  text: string;
  maxChars: number;
  expanded: boolean;
};

export type TextExpansion = {
  preview: string;
  isLong: boolean;
  expanded: boolean;
  toggle: () => void;
};

export function useTextExpansion(text: string, maxChars: number): TextExpansion {
  const [state, setState] = useState<ExpansionState>({ text, maxChars, expanded: false });
  const changed: boolean = state.text !== text || state.maxChars !== maxChars;

  if (changed) {
    setState({ text, maxChars, expanded: false });
  }

  const expanded: boolean = !changed && state.expanded;
  const isLong: boolean = text.length > maxChars;
  const preview: string = isLong && !expanded ? text.slice(0, maxChars) + '…' : text;

  function toggle(): void {
    setState((current: ExpansionState): ExpansionState => ({
      text,
      maxChars,
      expanded: !current.expanded,
    }));
  }

  return { preview, isLong, expanded, toggle };
}
