import { useState, type CSSProperties, type ReactElement } from 'react';

export type Row = { id: string; label: string; score: number | null };
export type Props = { rows: Row[] };

type SortDirection = 'none' | 'ascending' | 'descending';
type IndexedRow = { row: Row; index: number };

const panelStyle: CSSProperties = {
  backgroundColor: '#f2f6fc',
  color: '#1d3150',
  padding: 16,
  display: 'grid',
  gap: 8,
};

export function Component({ rows }: Props): ReactElement {
  const [direction, setDirection] = useState<SortDirection>('none');
  const ordered: IndexedRow[] = rows.map((row: Row, index: number): IndexedRow => ({ row, index }));

  if (direction !== 'none') {
    ordered.sort((left: IndexedRow, right: IndexedRow): number => {
      const a: number | null = left.row.score;
      const b: number | null = right.row.score;
      if (a === null && b === null) return left.index - right.index;
      if (a === null) return 1;
      if (b === null) return -1;
      if (a === b) return left.index - right.index;
      return direction === 'ascending' ? a - b : b - a;
    });
  }

  function toggleSort(): void {
    setDirection((current: SortDirection): SortDirection => current === 'ascending' ? 'descending' : 'ascending');
  }

  return (
    <section data-testid="panel" style={panelStyle}>
      <button type="button" onClick={toggleSort}>Sort score</button>
      <table aria-label="Rows">
        <thead>
          <tr>
            <th scope="col">Label</th>
            <th scope="col" aria-sort={direction}>Score</th>
          </tr>
        </thead>
        <tbody>
          {ordered.map(({ row }: IndexedRow): ReactElement => (
            <tr key={row.id}>
              <td>{row.label}</td>
              <td>{row.score === null ? '—' : row.score}</td>
            </tr>
          ))}
        </tbody>
      </table>
      {rows.length === 0 && <p role="status">No rows</p>}
    </section>
  );
}
