import { useState, type ChangeEvent, type CSSProperties, type ReactElement } from 'react';

export type Unit = 'C' | 'F';
export type Props = { initialValue: string; initialUnit: Unit };

type Theme = {
  colors: { panel: string; text: string };
  spacing: { panel: number; gap: number };
};

const theme: Theme = {
  colors: { panel: '#f2f6fc', text: '#1d3150' },
  spacing: { panel: 16, gap: 8 },
};

const panelStyle: CSSProperties = {
  backgroundColor: theme.colors.panel,
  color: theme.colors.text,
  padding: theme.spacing.panel,
  display: 'grid',
  gap: theme.spacing.gap,
};

function convert(raw: string, unit: Unit): number | null {
  const trimmed: string = raw.trim();
  if (!/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(trimmed)) return null;
  const value: number = Number(trimmed);
  if (!Number.isFinite(value)) return null;
  const result: number = unit === 'C' ? value * 9 / 5 + 32 : (value - 32) * 5 / 9;
  return Number.isFinite(result) ? result : null;
}

export function Component({ initialValue, initialUnit }: Props): ReactElement {
  const [value, setValue] = useState<string>(initialValue);
  const [unit, setUnit] = useState<Unit>(initialUnit);
  const targetUnit: Unit = unit === 'C' ? 'F' : 'C';
  const result: number | null = convert(value, unit);
  const formatted: string | null = result === null ? null : result.toFixed(2);

  function changeValue(event: ChangeEvent<HTMLInputElement>): void {
    setValue(event.currentTarget.value);
  }

  function changeUnit(event: ChangeEvent<HTMLSelectElement>): void {
    const nextUnit: string = event.currentTarget.value;
    if (nextUnit === 'C' || nextUnit === 'F') setUnit(nextUnit);
  }

  function swap(): void {
    if (formatted === null) return;
    setValue(formatted);
    setUnit(targetUnit);
  }

  return (
    <section data-testid="panel" style={panelStyle}>
      <label>
        Temperature
        <input type="text" value={value} onChange={changeValue} aria-invalid={formatted === null || undefined} />
      </label>
      <label>
        From unit
        <select value={unit} onChange={changeUnit}>
          <option value="C">C</option>
          <option value="F">F</option>
        </select>
      </label>
      <output aria-label="Converted">
        {formatted === null ? 'Invalid temperature' : `${formatted} ${targetUnit}`}
      </output>
      <button type="button" disabled={formatted === null} onClick={swap}>Swap</button>
    </section>
  );
}
```

작은 변환 기능을 한 파일에 모으고 디자인 값은 토큰으로 관리하며 상태와 계산 함수의 타입을 명시했습니다. 입력 원문은 그대로 보존하고 십진수 문법과 계산 결과의 유한성을 확인한 뒤, Swap에서만 입력을 변환 결과로 교체합니다.

