import { useState } from 'react';

type ExpansionState = {
  text: string;
  maxChars: number;
  expanded: boolean;
};

export type TextExpanderModel = {
  preview: string;
  canToggle: boolean;
  expanded: boolean;
  toggle: () => void;
};

export function useTextExpander(text: string, maxChars: number): TextExpanderModel {
  const [state, setState] = useState<ExpansionState>({
    text,
    maxChars,
    expanded: false,
  });
  const sameInput: boolean = state.text === text && state.maxChars === maxChars;

  if (!sameInput) {
    setState({ text, maxChars, expanded: false });
  }

  const expanded: boolean = sameInput && state.expanded;
  const canToggle: boolean = text.length > maxChars;
  const preview: string = canToggle && !expanded
    ? text.slice(0, maxChars) + '…'
    : text;

  function toggle(): void {
    setState({ text, maxChars, expanded: !expanded });
  }

  return { preview, canToggle, expanded, toggle };
}
